<?php
namespace App\Services\Payments;
use App\Jobs\SendOrderConfirmation;use App\Models\Payment;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class PaymentStateService {public function apply(Payment $payment,string $status,?string $gatewayReference,array $metadata=[]):Payment{return DB::transaction(function()use($payment,$status,$gatewayReference,$metadata){$payment=Payment::lockForUpdate()->with('order')->findOrFail($payment->id);if(round((float)$payment->amount,2)!==round((float)$payment->order->total,2))throw ValidationException::withMessages(['payment'=>['Payment amount does not match its order.']]);if($payment->status===$status)return $payment;$allowed=['unpaid'=>['pending','paid','failed'],'pending'=>['paid','failed'],'failed'=>['paid'],'paid'=>['refunded'],'refunded'=>[]];if(!in_array($status,$allowed[$payment->status]??[],true))throw ValidationException::withMessages(['payment'=>['Invalid payment state transition.']]);$payment->forceFill(['status'=>$status,'gateway_reference'=>$gatewayReference?:$payment->gateway_reference,'paid_at'=>$status==='paid'?now():$payment->paid_at,'gateway_metadata'=>$metadata])->save();if($status==='paid'){$payment->order->update(['status'=>'confirmed']);SendOrderConfirmation::dispatch($payment->order_id)->afterCommit();}return $payment;});}}
